/* hstaster-nov3 (audit12 #12; roadmap "a reviewed 6-8 step taster per subject"): the Quick start that a High School learner sees before Part 1 of
   each subject's first High School lesson (academics/hs-taster.js says when). One core idea, 6-8 steps, about 350 words or fewer (caption plus
   Try-it prompt), at most 2 Try-its, each answerable from the steps just read. Our own wording. A Quick start never rewords the lesson: the
   lesson's steps, Try-its, pool and question ids are untouched, and a Quick start Try-it never credits an answer, a point or a retirement
   (main.js lessonStep). Every number marked fictional is invented; maths is checked by derivation, code by running it in Python 3.

   Each entry carries its own review record (`review`, also written above it): what was checked, against which source, and the limits.
   Sources read 3 Nov 2026. Britannica refused automated reading (HTTP 403) and was not used; OpenStax College Physics was not used (CC BY-NC-SA,
   and it bars use for training language models). Loaded lazily, with the lesson. */
const B=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const PS=(title,texts)=>({t:'passages',title,texts,small:true});
const PG=(title,lines)=>({t:'program',title,lines:lines.map((l,i)=>`${i+1}. ${l}`)});
const C=(prompt,answer,options,hint)=>({prompt:`Try it: ${prompt}`,answer:String(answer),options:options.map(String),hint});
const ABC=(q,a,b,c)=>`${q} A: ${a}, B: ${b}, C: ${c}. Answer A, B or C.`;

export const TASTERS={
/* Math 1. Facts reviewed: 1 foot = 12 inches exactly (NIST Handbook 44, Appendix C, general tables of units); 1 hour = 60 minutes; every product
   and quotient by derivation (5 x 12 = 60, 48 / 12 = 4, 180 / 60 = 3). Limits: none beyond the arithmetic. */
'math-h-math-1-expressions-equations-and-units':{review:'Facts reviewed 3 Nov 2026: 1 foot = 12 inches exactly (NIST Handbook 44, Appendix C); 1 hour = 60 minutes; all arithmetic by derivation. Limits: unit conversion only; no fictional data.',steps:[
 {say:'Numbers in real problems come with units: 3 feet, 20 minutes, 15 dollars. The unit says what the number measures, so keep it beside the number.',pic:B('A number and its unit',['3 feet','20 minutes','15 dollars'],['a length','a time','money'])},
 {say:'12 inches and 1 foot are the same length. So the fraction 12 inches ÷ 1 foot equals 1, and multiplying by 1 never changes an amount.',pic:B('A fraction equal to 1',['1 foot = 12 inches','12 inches ÷ 1 foot = 1'])},
 {say:'To change feet into inches, multiply by that fraction. Feet is on the top and on the bottom, so it cancels: 3 feet × (12 inches ÷ 1 foot) = 36 inches.',pic:B('Feet into inches',['3 feet × (12 inches ÷ 1 foot)','= 36 inches'])},
 {say:'Your turn. Set the fraction up so feet cancel, then multiply.',pic:B('Feet into inches',['5 feet × (12 inches ÷ 1 foot)','= ? inches']),check:C('use 12 inches ÷ 1 foot. How many inches are in 5 feet?',60,[17,50,60],'Multiply 5 by 12: feet cancel and inches are left.')},
 {say:'To go the other way, flip the fraction so the old unit is on the bottom: 48 inches × (1 foot ÷ 12 inches) = 4 feet.',pic:B('Inches into feet',['48 inches × (1 foot ÷ 12 inches)','= 4 feet'])},
 {say:'Time converts the same way, because 1 hour is 60 minutes. Put minutes on the bottom so they cancel.',pic:B('Minutes into hours',['180 minutes × (1 hour ÷ 60 minutes)','= ? hours']),check:C('180 minutes × (1 hour ÷ 60 minutes) is how many hours?',3,[3,120,240],'Minutes cancel, so divide: 180 ÷ 60.')},
 {say:'That is the whole trick: multiply by a fraction equal to 1, set up so the old unit cancels. The full lesson uses it for rates such as kilometers per hour, then for expressions and equations.',pic:B('The rule',['Multiply by a fraction equal to 1','Put the old unit on the bottom','It cancels; the new unit is left'])}]},

/* Math 2. Facts reviewed by derivation: 7 x 7 = 49; sqrt4 sqrt9 = sqrt36 = 6; sqrt12 = 2 sqrt3; sqrt50 = 5 sqrt2; 3 sqrt5 + 4 sqrt5 = 7 sqrt5;
   sqrt2 + sqrt3 (about 3.146) is not sqrt5 (about 2.236); sqrt(a) sqrt(b) = sqrt(ab) for a, b >= 0. Limits: real square roots only. */
'math-h-math-2-radicals-and-complex-numbers':{review:'Facts reviewed 3 Nov 2026 by derivation: 7 × 7 = 49; √4·√9 = √36 = 6; √12 = 2√3; √50 = 5√2; 3√5 + 4√5 = 7√5; √2 + √3 ≈ 3.146 ≠ √5 ≈ 2.236; √a·√b = √(ab) for a, b ≥ 0. Limits: real square roots only.',steps:[
 {say:'A square root undoes squaring. √49 = 7, because 7 × 7 = 49. A perfect square, such as 4, 9, 16 or 25, has a whole-number square root.',pic:B('Square roots',['√49 = 7','because 7 × 7 = 49'])},
 {say:'Square roots multiply under one root: √4 · √9 = √36 = 6. Check it another way: √4 is 2, √9 is 3, and 2 × 3 = 6.',pic:B('Multiply under one root',['√4 · √9 = √36','= 6'])},
 {say:'The rule runs backward to simplify. Find the largest perfect square factor and pull it out: √12 = √4 · √3 = 2√3, because √4 is 2.',pic:B('Simplify √12',['√12 = √4 · √3','= 2√3'])},
 {say:'Your turn. Look for the largest perfect square that divides 50.',pic:B('Simplify √50',['√50 = √? · √2','= a√2']),check:C('written in simplest form, √50 = a√2. What is a?',5,[5,10,25],'50 = 25 × 2, and √25 = 5.')},
 {say:'Like radicals are the same root of the same number, and they combine like like terms: 2√3 + 5√3 = 7√3. Unlike ones do not: √2 + √3 is not √5.',pic:B('Only like radicals combine',['2√3 + 5√3 = 7√3','√2 + √3 ≠ √5'])},
 {say:'Like radicals add the numbers in front and keep the root.',pic:B('Add like radicals',['3√5 + 4√5 = b√5']),check:C('3√5 + 4√5 = b√5. What is b?',7,[7,12,20],'Add the numbers in front: 3 + 4.')},
 {say:'So far: multiply under one root, pull out perfect squares, and combine only like radicals. The full lesson goes on to rational and irrational numbers, then to complex numbers.',pic:B('Three rules',['Multiply: √a · √b = √(ab), a, b ≥ 0','Simplify: pull out a perfect square','Add: only like radicals'])}]},

/* AP Precalculus Unit 1, Polynomial and Rational Functions (College Board AP Students course page: "Describing how quantities change with respect
   to each other"). Facts reviewed by derivation: f(3) = 7 and f(5) = 11 for f(x) = 2x + 1; for g(x) = x^2 the average rate of change is
   (9 - 1)/(3 - 1) = 4 on [1, 3] and (4 - 0)/(2 - 0) = 2 on [0, 2]. Limits: none beyond the arithmetic. */
'math-h-ap-precalc-polynomial-and-rational-functions':{review:'Facts reviewed 3 Nov 2026: unit name and focus from the College Board AP Precalculus course page (Unit 1, "Describing how quantities change with respect to each other"); all values by derivation (f(3) = 7, f(5) = 11 for 2x + 1; x² has average rate 4 on [1, 3] and 2 on [0, 2]). Limits: average rates only.',steps:[
 {say:'A function gives each input exactly one output. For f(x) = 2x + 1, the input 3 gives the output 7, because 2 × 3 + 1 = 7.',pic:B('One input, one output',['f(x) = 2x + 1','f(3) = 2 × 3 + 1','= 7'])},
 {say:'Precalculus studies how outputs change as inputs change. For f(x) = 2x + 1, each time x goes up by 1, the output goes up by 2.',pic:{t:'setups',title:'f(x) = 2x + 1',head:'x',cols:['f(x)'],rows:[['0','1'],['1','3'],['2','5'],['3','7']]}},
 {say:'Your turn: put the input into the rule.',pic:B('f(x) = 2x + 1',['f(5) = ?']),check:C('for f(x) = 2x + 1, what is f(5)?',11,[7,10,11],'Double 5, then add 1.')},
 {say:'The average rate of change from x = a to x = b is the change in output divided by the change in input. On a graph it is the slope of the line through those two points.',pic:B('Average rate of change',['(f(b) - f(a)) ÷ (b - a)'],['output change ÷ input change'])},
 {say:'For g(x) = x² from x = 1 to x = 3: g(3) = 9 and g(1) = 1, so the rate is (9 - 1) ÷ (3 - 1) = 8 ÷ 2 = 4 output units per input unit.',pic:B('g(x) = x² on [1, 3]',['(9 - 1) ÷ (3 - 1)','= 8 ÷ 2','= 4'])},
 {say:'Now find a rate on a different interval of the same function.',pic:B('g(x) = x² on [0, 2]',['(g(2) - g(0)) ÷ (2 - 0)','= ?']),check:C('for g(x) = x², what is the average rate of change from x = 0 to x = 2?',2,[1,2,4],'g(2) = 4 and g(0) = 0, so divide 4 - 0 by 2 - 0.')},
 {say:'For 2x + 1 the rate is always 2, but for x² it changes from one interval to the next. Unit 1 of AP Precalculus studies such rates for polynomial and rational functions.',pic:B('Rates compared',['2x + 1: always 2','x²: 2 on [0, 2], 4 on [1, 3]'])}]},

/* AP Calculus AB Unit 1, Limits and Continuity (College Board AP Students course page: "How limits help us to handle change at an instant").
   Facts reviewed by derivation: ((2 + h)^2 - 4)/h = 4 + h for h != 0; h = 0.1, 0.01, 0.001 give 4.1, 4.01, 4.001; (x^2 - 1)/(x - 1) = x + 1
   for x != 1, so its limit at 1 is 2. The definition is stated informally, as the course does at this point. The position function is fictional. */
'math-h-ap-calc-ab-limits-and-continuity':{review:'Facts reviewed 3 Nov 2026: unit name and focus from the College Board AP Calculus AB course page (Unit 1, "How limits help us to handle change at an instant"); all algebra by derivation (((2 + h)² - 4) ÷ h = 4 + h for h ≠ 0; (x² - 1) ÷ (x - 1) = x + 1 for x ≠ 1). Limits: the limit is defined informally; s(t) = t² is fictional.',steps:[
 {say:'Calculus asks how fast something changes at one instant. An average rate needs two times, but an instant has only one. A limit is the tool that closes that gap.',pic:B('Average and instant',['average rate: two times','instant rate: one time','a limit closes the gap'])},
 {say:'Take a fictional position s(t) = t² meters. From t = 2 to t = 2 + h seconds, the average velocity works out to 4 + h meters per second. You cannot just set h = 0: that would divide by zero.',pic:B('Average velocity from t = 2',['((2 + h)² - 4) ÷ h','= (4h + h²) ÷ h','= 4 + h'])},
 {say:'Make h smaller and smaller: h = 0.1 gives 4.1, h = 0.01 gives 4.01, and h = 0.001 gives 4.001. The averages get as close to 4 as you like, so the velocity at t = 2 is 4 meters per second.',pic:{t:'setups',title:'4 + h as h shrinks',head:'h',cols:['average velocity'],rows:[['0.1','4.1'],['0.01','4.01'],['0.001','4.001']]}},
 {say:'We write lim (x → a) f(x) = L when f(x) gets as close to L as we like for every x close enough to a, but not equal to a. The value at a itself does not matter.',pic:B('Limit notation',['lim (x → a) f(x) = L'])},
 {say:'Your turn. The function below is not defined at x = 1, but its limit there can still exist.',pic:B('Near x = 1',['(x² - 1) ÷ (x - 1)','= x + 1, for x ≠ 1']),check:C('for x ≠ 1, f(x) = (x² - 1) ÷ (x - 1) is the same as x + 1. What is lim (x → 1) f(x)?',2,[0,1,2],'Near x = 1, x + 1 is near 1 + 1.')},
 {say:'A two-sided limit needs both sides to agree. If f(x) nears 3 from the left of a and 5 from the right, the limit at a does not exist.',pic:B('Both sides must agree',['from the left: 3','from the right: 5','so no two-sided limit'])},
 {say:'One more, from both sides.',pic:B('Near x = 4',['from the left: 6','from the right: 6','f(4) = 9']),check:C('as x nears 4, f(x) nears 6 from the left and 6 from the right, but f(4) = 9. What is lim (x → 4) f(x)?',6,[6,9,15],'Both sides agree on 6, and the value at 4 itself does not matter.')}]},

/* Intro to Programming (Python), Variables and Data Types. Facts reviewed by running each program in Python 3 (3 Nov 2026): x = 4; x = x * 3
   prints 12; "5" + "2" prints 52; type(7), type(7.5), type("7") are int, float, str; "3" + "4" is "34"; "3" + 4 raises TypeError; score and
   Score are different names. Limits: Python 3 only. */
'cs-h-programming-python-variables-and-data-types':{review:'Facts reviewed 3 Nov 2026 by running each program in Python 3: x = 4; x = x * 3 prints 12; "5" + "2" prints 52; type(7), type(7.5), type("7") are int, float and str; "3" + "4" is "34"; "3" + 4 raises TypeError; score and Score are two names. Limits: Python 3 only.',steps:[
 {say:'A variable is a name for a value your program remembers. In Python, score = 10 stores 10 under the name score. The single equals sign means store, not equals.',pic:PG('Store a value',['score = 10'])},
 {say:'Python works out the right side first, then stores the result. So score = score + 5 reads the old score, 10, adds 5 and stores 15 back under the same name.',pic:PG('Update a value',['score = 10','score = score + 5','print(score)'])},
 {say:'Your turn. Follow the program one line at a time.',pic:PG('What is printed?',['x = 4','x = x * 3','print(x)']),check:C('Code: x = 4; x = x * 3; print(x) What is printed?',12,[4,7,12],'x starts at 4; the second line stores 4 * 3.')},
 {say:'Every value has a type. 7 is an int, a whole number. 7.5 is a float, a number with a decimal point. "7" in quotes is a str, a string of text.',pic:{t:'setups',title:'Three types',head:'Value',cols:['Type'],rows:[['7','int'],['7.5','float'],['"7"','str']]}},
 {say:'Types change what an operator does. 3 + 4 is 7, but "3" + "4" joins two strings into "34". Mixing them, as in "3" + 4, stops the program with a TypeError.',pic:PG('Same sign, different types',['print(3 + 4)','print("3" + "4")'])},
 {say:'Look closely at the quotes before you answer.',pic:PG('What is printed?',['a = "5"','b = "2"','print(a + b)']),check:C('Code: a = "5"; b = "2"; print(a + b) What is printed?',52,[3,7,52],'Both values are strings, so + joins them.')},
 {say:'Names are case sensitive, so score and Score are two different variables. The full lesson goes on to naming rules, input() and converting between types.',pic:PG('Two different names',['score = 10','Score = 1','print(score, Score)'])}]},

/* AP Computer Science Principles, Big Idea 1, Creative Development. Facts reviewed against the College Board AP CSP Course and Exam Description
   (read 3 Nov 2026): a program is a collection of program statements that performs a specific task when run by a computer, often called
   software (CRD-2.B); program inputs are data sent to a computer for processing by a program, in forms such as tactile, audio, visual or
   text (CRD-2.C); output is usually based on input or prior state (CRD-2.D); logic, syntax and run-time error definitions (CRD-2.I). Big Idea 1
   description from the AP Students course page. Paraphrased. Limits: the iterative and incremental development processes were not
   re-read this pass and stay in the full lesson; the apps are fictional. */
'cs-h-ap-csp-creative-development':{review:'Facts reviewed 3 Nov 2026 against the College Board AP CSP Course and Exam Description (program, CRD-2.B; inputs, CRD-2.C; output, CRD-2.D; logic, syntax and run-time errors, CRD-2.I) and the AP Students course page (Big Idea 1). Paraphrased. Limits: development processes left to the full lesson; the apps are fictional.',steps:[
 {say:'In AP Computer Science Principles, a program is a set of statements that does a specific task when a computer runs it. Programs are often called software.',pic:B('A program',['statements','a specific task','run by a computer'])},
 {say:'Programs take inputs, data sent to the program to process, such as a tap, a sound or typed text. A program\'s output is usually based on its input or on values it already holds.',pic:B('Input and output',['input: a tap, a sound, text','the program processes it','output: what comes back'])},
 {say:'Mistakes in programs have names. A syntax error breaks the rules of the programming language. A logic error lets the program run but makes it behave incorrectly or unexpectedly. A run-time error happens while the program is running.',pic:B('Three kinds of error',['syntax error','logic error','run-time error'],['breaks the rules','runs, wrong result','while running'])},
 {say:'Your turn. The program runs, so ask what kind of mistake gives a wrong answer.',pic:B('A fictional average',['(4 + 8 + 9) ÷ 2 = 10.5','expected: (4 + 8 + 9) ÷ 3 = 7']),check:C(ABC('a fictional app should average 4, 8 and 9, but it divides their sum by 2 and shows 10.5 instead of 7. Which kind of error is that?','a syntax error','a logic error','a run-time error'),'B',['A','B','C'],'The program runs and follows the language\'s rules, but the result is wrong.')},
 {say:'Errors are found by testing: run the program with chosen inputs and compare what it shows with what you expected.',pic:B('Testing',['choose an input','predict the output','run it and compare'])},
 {say:'One more kind. Think about when the problem shows up.',pic:B('A fictional crash',['the program starts','partway through, it stops','an error message appears']),check:C(ABC('a fictional program starts normally, then stops partway through running with an error message. Which kind of error is that?','a run-time error','a syntax error','a logic error'),'A',['A','B','C'],'It happened while the program was running.')},
 {say:'Creative Development is about how people work together to design and develop programs. The full lesson starts with collaboration and pair programming.',pic:B('Creative Development',['collaboration','program design','finding and fixing errors'])}]},

/* AP World History: Modern, Unit 1, The Global Tapestry, c. 1200 to c. 1450 (College Board AP Students course page). Song dynasty begins 960;
   upper levels of government staffed by "scholar-officials selected through competitive written examinations"; population grew rapidly
   and more people lived in cities (Columbia University, Asia for Educators, "The Song Dynasty in China" module, index). Champa rice from
   Champa, "a kingdom then located near the Mekong River Delta in what is now Vietnam" (quoting Lynda Shaffer), ripened faster than earlier
   early-ripening rice, made double-cropping possible in some areas and triple-cropping in some places (same module, "Rice Cultivation").
   Limits: no end date for the Song is given (sources differ between 1276 and 1279); causes are stated as "helped", not as sole causes. */
'history-h-ap-world-the-global-tapestry-1200-1450':{review:'Facts reviewed 3 Nov 2026: unit name and dates from the College Board AP World History: Modern course page; Song dynasty from 960, examinations, population and cities from Columbia University Asia for Educators, "The Song Dynasty in China" (index); Champa rice from the same module, "Rice Cultivation". Limits: no end date for the Song (sources give 1276 or 1279); causes are hedged.',steps:[
 {say:'AP World History: Modern begins around 1200. Its first unit, The Global Tapestry, covers about 1200 to 1450 and asks how states and societies across the world developed.',pic:B('AP World, Unit 1',['The Global Tapestry','c. 1200 to c. 1450'])},
 {say:'Start in East Asia, with China\'s Song dynasty, which began in 960. The upper levels of its government were staffed by scholar-officials chosen through competitive written examinations.',pic:B('Song China',['began in 960','scholar-officials','chosen by written examinations'])},
 {say:'Your turn. Think about how a Song official got the job.',pic:B('Song government',['Who ran it?','How were they chosen?']),check:C(ABC('how were the scholar-officials of Song China chosen?','by a lottery','by birth alone','by competitive written examinations'),'C',['A','B','C'],'The step said they were chosen through competitive written examinations.')},
 {say:'Food changed too. A fast-ripening rice reached China from Champa, a kingdom in what is now Vietnam. In some areas farmers could grow two crops a year, and in some places even three.',pic:B('Champa rice',['from Champa (now in Vietnam)','ripens fast','two crops a year in some areas'])},
 {say:'More food could feed more people. China\'s population grew rapidly in the Song period, and more and more people lived in cities.',pic:B('Cause and effect',['more rice','more people','more people in cities'])},
 {say:'Pick the change that was about food.',pic:B('Song China',['Which change grew more food?']),check:C(ABC('which change helped Song China grow more food?','Champa rice','written examinations','larger cities'),'A',['A','B','C'],'Fast-ripening Champa rice allowed more than one crop a year in some areas.')},
 {say:'That is how AP World reads the past: a cause, such as a new rice, and its effects, such as more people and bigger cities. The full lesson goes on from China to other regions of the world.',pic:B('Reading history',['a cause','its effects','across regions'])}]},

/* AP United States History, Period 1: 1491-1607, and the nine periods to the present (College Board AP Students course page). Columbus's 1492
   voyage and his four voyages in all, the last in 1502 (Library of Congress, "1492: An Ongoing Voyage", Christopher Columbus section).
   Jamestown 1607 and the beginning of successful English colonization of North America there (National Park Service, Historic Jamestowne).
   The Columbian Exchange as the transfer of organisms between the hemispheres after Columbus's voyage, with New World crops such as maize and
   potatoes spreading in the Old World (Hünemeier et al., "The Columbian Exchange as a source of adaptive introgression in human
   populations", Biology Direct 2016, PMC4818900). 1607 - 1492 = 115 by derivation. Limits: why the course starts in 1491 is stated as what it
   allows, not as the College Board's stated reason. */
'history-h-apush-period-1-1491-1607':{review:'Facts reviewed 3 Nov 2026: periods from the College Board AP United States History course page; 1492 and four voyages from the Library of Congress exhibition "1492: An Ongoing Voyage"; Jamestown 1607 from the National Park Service (Historic Jamestowne); the Columbian Exchange and New World crops (maize, potatoes) from Biology Direct 2016 (PMC4818900); 1607 - 1492 = 115 by derivation. Limits: the reason for starting in 1491 is hedged.',steps:[
 {say:'AP United States History splits the past into nine periods. Period 1 runs from 1491 to 1607.',pic:B('APUSH periods',['Period 1: 1491 to 1607','Period 2: 1607 to 1754','… Period 9: 1980 to the present'])},
 {say:'Starting in 1491, the year before Columbus\'s first voyage in 1492, lets the course look at the Americas before Europeans arrived to stay.',pic:B('The start of Period 1',['1491: the Americas','1492: Columbus\'s first voyage'])},
 {say:'Columbus made four voyages in all, and the report of his 1492 voyage made him famous across Europe.',pic:B('Columbus',['1492: first voyage','four voyages in all'])},
 {say:'Period 1 ends in 1607, the year of the English settlement at Jamestown, Virginia, where successful English colonization of North America began.',pic:B('The end of Period 1',['1607: Jamestown, Virginia'])},
 {say:'Your turn. Subtract the earlier year from the later one.',pic:B('From Columbus to Jamestown',['1492 → 1607','? years']),check:C('how many years passed between Columbus\'s first voyage in 1492 and Jamestown in 1607?',115,[105,115,125],'1607 - 1492 = 115.')},
 {say:'After 1492, plants, animals and diseases crossed between the hemispheres: historians call this the Columbian Exchange. Crops from the Americas, such as maize and potatoes, spread across the rest of the world.',pic:B('The Columbian Exchange',['Americas → rest of the world','maize, potatoes'])},
 {say:'One more, from the step you just read.',pic:B('The Columbian Exchange',['Which crop came from the Americas?']),check:C(ABC('which crop spread from the Americas to the rest of the world in the Columbian Exchange?','wheat','maize','rice'),'B',['A','B','C'],'Maize and potatoes are crops from the Americas.')}]},

/* AP United States Government and Politics, Unit 1, Foundations of American Democracy ("The ideals of democracy as shown in the Declaration of
   Independence and the Constitution", College Board AP Students course page). Quotations and the date line "In Congress, July 4, 1776" from the
   National Archives transcription of the Declaration. Constitution signed September 17, 1787 (National Archives, "A More Perfect Union").
   Separation of powers, three branches, Congress makes laws, the executive led by the President enforces them, the judicial branch headed by
   the Supreme Court reviews the other two (Cornell LII Wex, "separation of powers"). 1787 - 1776 = 11. Limits: the term popular sovereignty is
   left to the full lesson (no primary definition was read this pass). */
'history-h-ap-gov-foundations-of-american-democracy':{review:'Facts reviewed 3 Nov 2026: Unit 1 from the College Board AP US Government and Politics course page; quotations and July 4, 1776 from the National Archives transcription of the Declaration; signing on September 17, 1787 from the National Archives, "A More Perfect Union"; the three branches from Cornell LII Wex, "separation of powers". Limits: the term popular sovereignty is left to the full lesson.',steps:[
 {say:'AP United States Government and Politics starts with the foundations of American democracy: the ideas in the Declaration of Independence and the Constitution.',pic:B('Unit 1',['the Declaration of Independence','the Constitution'])},
 {say:'The Declaration is dated July 4, 1776. It says people are “endowed by their Creator with certain unalienable Rights,” and that governments get “their just powers from the consent of the governed.”',pic:B('The Declaration, 1776',['“certain unalienable Rights”','“the consent of the governed”'])},
 {say:'Consent of the governed means a government\'s rightful power comes from the people it governs, not from the rulers themselves.',pic:B('Consent of the governed',['the people','give power to','the government'])},
 {say:'Your turn. Answer from the Declaration\'s own words.',pic:B('The Declaration',['Where does a government get','its just powers?']),check:C(ABC('in the Declaration, where do governments get their just powers?','from the army','from the consent of the governed','from the king'),'B',['A','B','C'],'Governments derive “their just powers from the consent of the governed.”')},
 {say:'Eleven years later, on September 17, 1787, the Constitution was signed. It turned those ideas into institutions.',pic:B('From ideas to institutions',['1776: the Declaration','1787: the Constitution'])},
 {say:'One institution is the separation of powers: three branches kept separate, each able to check the others. Congress, the legislative branch, makes laws. The executive branch, led by the President, enforces them. The judicial branch, headed by the Supreme Court, reviews the other two.',pic:B('Three branches',['legislative: Congress','executive: the President','judicial: the courts'],['makes laws','enforces laws','reviews actions'])},
 {say:'One more, from the three branches.',pic:B('Three branches',['Which branch makes laws?']),check:C(ABC('which branch of government makes the laws?','the judicial branch','the executive branch','the legislative branch'),'C',['A','B','C'],'Congress, the legislative branch, makes laws.')}]},

/* World Geography, Maps and geospatial tools. Latitude lines (parallels) start at the equator, 0 degrees, and reach 90 degrees at each pole;
   each degree of latitude covers about 111 km (NOAA National Ocean Service, "What is latitude?"). Meridians run north-south from pole to pole;
   the prime meridian through Greenwich, England, is 0 degrees; the antimeridian is 180 degrees (NOAA National Ocean Service, "What is
   longitude?"). 5 x 111 = 555 and 10 x 111 = 1,110 by derivation. Limits: the 111 km figure is "about"; towns are fictional. */
'geography-h-world-geography-maps-and-geospatial-tools':{review:'Facts reviewed 3 Nov 2026: latitude, parallels, 0° to 90°, about 111 km per degree from NOAA National Ocean Service, "What is latitude?"; meridians, the prime meridian through Greenwich (0°), 180° from NOAA National Ocean Service, "What is longitude?"; distances by derivation. Limits: 111 km is approximate; the towns are fictional.',steps:[
 {say:'Every place on Earth has a latitude and a longitude, like an address on a grid of imaginary lines.',pic:B('A global address',['latitude: north or south','longitude: east or west'])},
 {say:'Lines of latitude, called parallels, start at the equator, 0°, and reach 90° at each pole. Latitude says how many degrees north or south of the equator a place is.',pic:B('Latitude',['equator: 0°','North Pole: 90° N','South Pole: 90° S'])},
 {say:'Lines of longitude, called meridians, run from pole to pole. The prime meridian, through Greenwich, England, is 0°, and longitude counts east or west of it, up to 180°.',pic:B('Longitude',['prime meridian: 0°','Greenwich, England','up to 180° east or west'])},
 {say:'Your turn, from the line where latitude starts.',pic:B('Latitude',['the equator: ?']),check:C('what is the latitude of the equator?','0°',['0°','90°','180°'],'Latitude starts at the equator, 0°, and reaches 90° at the poles.')},
 {say:'Each degree of latitude covers about 111 kilometers on Earth\'s surface. So two places on one meridian, 10° of latitude apart, are about 1,110 km apart.',pic:B('One degree of latitude',['about 111 km','10° apart: about 1,110 km'])},
 {say:'Find the difference in degrees first, then multiply.',pic:B('Two fictional towns, one meridian',['20° N and 15° N','about ? km apart']),check:C('two fictional towns lie on one meridian, at 20° N and 15° N. About how many kilometers apart are they?',555,[111,555,3885],'They are 5° apart, and 5 × 111 = 555.')},
 {say:'Latitude says how far north or south, and longitude says how far east or west. Together they pin down one place. The full lesson goes on to map projections and the tools geographers use.',pic:B('Pin down a place',['latitude + longitude','= one place'])}]},

/* AP Human Geography, Thinking geographically. Map scale as a ratio and large versus small scale: 1:24,000 is a large scale (small area, more
   detail; one inch to 24,000 inches); 1:250,000 and smaller show large areas with details limited to major features (USGS Fact Sheet
   FS-015-02, "Map Scales", and the USGS Maps booklet). 100 cm = 1 m and 1,000 m = 1 km (SI); 4 x 50,000 = 200,000 cm = 2 km by derivation.
   Limits: the AP term "scale of analysis" is left to the full lesson; the map and villages are fictional. */
'geography-h-ap-hug-thinking-geographically':{review:'Facts reviewed 3 Nov 2026: ratio scales, 1:24,000 as a large scale with more detail and 1:250,000 and smaller as small scales from USGS Fact Sheet FS-015-02, "Map Scales", and the USGS Maps booklet; 100 cm = 1 m and 1,000 m = 1 km (SI); conversions by derivation. Limits: "scale of analysis" is left to the full lesson; the map is fictional.',steps:[
 {say:'Geographers think with maps, and every map has a scale: how much smaller the map is than the ground it shows.',pic:B('Map scale',['map distance','ground distance'])},
 {say:'A ratio scale such as 1 : 100,000 means 1 unit on the map stands for 100,000 of the same unit on the ground. So 1 cm on the map is 100,000 cm on the ground.',pic:B('1 : 100,000',['1 cm on the map','100,000 cm on the ground'])},
 {say:'There are 100 cm in a meter and 1,000 m in a kilometer, so 100,000 cm is 1 km. At 1 : 100,000, each map centimeter stands for 1 kilometer.',pic:B('Centimeters into kilometers',['100,000 cm = 1,000 m','= 1 km'])},
 {say:'Your turn. Multiply by the scale, then change the units.',pic:B('A fictional map, 1 : 50,000',['4 cm on the map','? km on the ground']),check:C('on a fictional map at 1 : 50,000, two villages are 4 cm apart. How many kilometers apart are they on the ground?',2,[0.5,2,20],'4 × 50,000 = 200,000 cm, and 100,000 cm is 1 km.')},
 {say:'A large-scale map, such as 1 : 24,000, shows a small area in detail. A small-scale map, such as 1 : 250,000, shows a large area, with only the major features.',pic:B('Large and small scale',['1 : 24,000: large scale','1 : 250,000: small scale'],['small area, detail','large area, less detail'])},
 {say:'The smaller the number after the colon, the larger the scale.',pic:B('Three scales',['1 : 24,000','1 : 250,000','1 : 1,000,000']),check:C(ABC('which of these map scales shows the most detail?','1 : 1,000,000','1 : 250,000','1 : 24,000'),'C',['A','B','C'],'1 : 24,000 is the largest scale here, so it shows a small area in the most detail.')},
 {say:'Remember: a scale is a ratio, and a large scale means a small area in more detail. The full lesson goes on to kinds of maps and the data geographers use.',pic:B('Scale',['a ratio','large scale: small area','small scale: large area'])}]},

/* AP Physics 1, Kinematics. A vector depends on direction, a scalar does not; speed is the scalar size of velocity; displacement, velocity and
   acceleration are vectors; the 50 mph to the northeast example (NASA Glenn Research Center, "Vectors and Scalars"). Displacement as the change
   in position and average velocity as displacement divided by the time interval (NASA Glenn, "Displacement, Velocity, Acceleration"). Distance
   as the length of the path is the course's definition. 30 - 10 = 20, 50 - 20 = 30, 24 / 4 = 6 by derivation. Limits: one dimension only;
   runner and cart are fictional. */
'science-h-acceleration':{review:'Facts reviewed 3 Nov 2026: scalars and vectors, speed and velocity, and the 50 mph northeast example from NASA Glenn Research Center, "Vectors and Scalars"; displacement and average velocity from NASA Glenn, "Displacement, Velocity, Acceleration"; arithmetic by derivation. Limits: motion in one dimension; the runner and cart are fictional.',steps:[
 {say:'Physics describes motion with two kinds of quantity. A scalar has only a size. A vector has a size and a direction.',pic:B('Two kinds of quantity',['scalar: size only','vector: size and direction'])},
 {say:'Speed is a scalar. Velocity, displacement and acceleration are vectors. 50 miles per hour is a speed; 50 miles per hour to the northeast is a velocity.',pic:B('Speed and velocity',['50 mph','50 mph to the northeast'],['a speed','a velocity'])},
 {say:'Displacement is the change in position: where you end minus where you started. Distance is the length of the whole path. Walk 30 m east, then 10 m west: you have gone 40 m but are only 20 m east of the start.',pic:B('Distance and displacement',['30 m east, then 10 m west','distance: 40 m','displacement: 20 m east'])},
 {say:'Your turn. Where does she end up, compared with where she started?',pic:B('A fictional runner',['50 m east, then 20 m west','displacement: ? m east']),check:C('a fictional runner goes 50 m east, then 20 m west. What is her displacement, in meters east?',30,[20,30,70],'Displacement is end minus start: 50 - 20 = 30 m east.')},
 {say:'Average velocity is displacement divided by the time it took. If the runner\'s 30 m east took 10 s, her average velocity is 3 m/s east.',pic:B('Average velocity',['30 m ÷ 10 s','= 3 m/s east'])},
 {say:'Divide the displacement by the time.',pic:B('A fictional cart',['24 m east in 4 s','? m/s east']),check:C('a fictional cart\'s displacement is 24 m east in 4 s. What is its average velocity, in m/s east?',6,[6,20,96],'24 ÷ 4 = 6.')},
 {say:'Average velocity uses displacement, not distance, so a round trip back to the start has an average velocity of zero. The full lesson goes on to acceleration and motion graphs.',pic:B('A round trip',['displacement: 0 m','average velocity: 0 m/s'])}]},

/* AP Chemistry, Atomic Structure and Properties (moles). The Avogadro constant 6.02214076 x 10^23 per mole, exact since the 2019 SI
   (NIST, "SI Redefinition: Mole"). Standard atomic weights H [1.00784, 1.00811], O [15.99903, 15.99977] (CIAAW), so H about 1.008 and O about
   16.00; the whole-number values 1 and 16 are labelled as rounded. 2 x 1 + 16 = 18; 2 x 16 = 32; 90/18 = 5; 54/18 = 3 by derivation.
   Limits: the jar is fictional; rounded masses only. */
'science-h-moles':{review:'Facts reviewed 3 Nov 2026: the Avogadro constant 6.02214076 × 10²³ from NIST, "SI Redefinition: Mole"; atomic weights of H and O from CIAAW (standard atomic weights), rounded and labelled so; arithmetic by derivation. Limits: rounded masses; the jar is fictional.',steps:[
 {say:'Chemists count particles in moles. One mole is exactly 6.02214076 × 10²³ particles, such as atoms or molecules: far too many to count one by one.',pic:B('One mole',['6.02214076 × 10²³ particles'])},
 {say:'Molar mass is the mass of one mole, in grams per mole. Add the atomic mass of every atom in the formula. Water, H₂O, has two hydrogen atoms and one oxygen atom.',pic:B('H₂O',['2 hydrogen atoms','1 oxygen atom'])},
 {say:'Hydrogen is about 1.008 and oxygen about 16.00 grams per mole. Rounded to 1 and 16, water is 2 × 1 + 16 = 18 grams per mole.',pic:B('Molar mass of water',['2 × 1 + 16','= 18 g/mol'])},
 {say:'Your turn. Count the atoms in the formula first.',pic:B('O₂',['2 oxygen atoms','? g/mol']),check:C('oxygen gas is O₂. Using O = 16, what is its molar mass, in g/mol?',32,[16,18,32],'Two oxygen atoms: 2 × 16 = 32.')},
 {say:'To turn grams into moles, divide by the molar mass: 90 g of water ÷ 18 g/mol = 5 mol.',pic:B('Grams into moles',['90 g ÷ 18 g/mol','= 5 mol'])},
 {say:'Divide the grams by the molar mass.',pic:B('A fictional jar of water',['54 g of H₂O','? mol']),check:C('a fictional jar holds 54 g of water (H₂O). Using 18 g/mol, how many moles is that?',3,[3,36,72],'54 ÷ 18 = 3.')},
 {say:'Grams measure mass; moles count particles. The full lesson goes on to molar masses of bigger formulas and to how atoms are built.',pic:B('Mass and amount',['grams: mass','moles: particles'])}]},

/* AP Biology, Chemistry of life. Water's polar bonding; hydrogen bonds as attractions between slightly positive hydrogen and slightly negative
   atoms of neighbouring molecules; cohesion as water-to-water attraction, adhesion as attraction to other materials; both help water climb in
   plants (USGS Water Science School, "Adhesion and Cohesion of Water" and its hydrogen-bond figure). pH 7 neutral (for pure water at 25 C),
   below 7 acidic, above 7 basic, each whole number a tenfold change, "pH of five is ten times more acidic than ... six" (USGS Water Science
   School, "pH and Water"; USGS TM 9-A6.4 for 25 C). 10 x 10 x 10 = 1,000. Limits: beading on a waxy leaf is described as water attracting
   itself more than the wax. */
'science-h-ap-bio-chemistry-of-life':{review:'Facts reviewed 3 Nov 2026: polarity, hydrogen bonds, cohesion and adhesion, water climbing plants from USGS Water Science School, "Adhesion and Cohesion of Water"; pH 7 neutral at 25 °C, acidic and basic, tenfold per unit from USGS Water Science School, "pH and Water", and USGS Techniques and Methods 9-A6.4; 10 × 10 × 10 = 1,000. Limits: the leaf example is simplified.',steps:[
 {say:'Life runs on water, and water\'s behavior comes from its charges. In a water molecule the oxygen side is slightly negative and the hydrogen side slightly positive, so water is polar.',pic:B('A polar molecule',['oxygen side: slightly negative','hydrogen side: slightly positive'])},
 {say:'Opposite charges attract, so a hydrogen of one water molecule is drawn to the oxygen of a neighbor. That attraction is a hydrogen bond.',pic:B('A hydrogen bond',['H of one molecule','is drawn to','O of the next'])},
 {say:'Hydrogen bonds make water stick to itself, called cohesion, and to other materials, called adhesion. Together they help water climb from a plant\'s roots to its leaves.',pic:B('Cohesion and adhesion',['cohesion','adhesion'],['water to water','water to other things'])},
 {say:'Your turn. Ask what is pulling on what.',pic:B('A drop on a waxy leaf',['water pulls on water','more than on the wax']),check:C('water beads into round drops on a waxy leaf because its molecules attract each other more than they attract the wax. Which property is that?','cohesion',['adhesion','cohesion','acidity'],'Water sticking to water is cohesion.')},
 {say:'pH measures how acidic or basic a solution is. For pure water at 25 °C, pH 7 is neutral. Below 7 is acidic, and above 7 is basic.',pic:B('The pH scale',['below 7: acidic','7: neutral','above 7: basic'])},
 {say:'Each step of 1 on the pH scale is a tenfold change: water at pH 5 is ten times more acidic than water at pH 6.',pic:B('Tenfold steps',['pH 6 → pH 5: 10 times','pH 6 → pH 4: 100 times'])},
 {say:'Count the steps, then multiply by ten for each one.',pic:B('pH 4 and pH 7',['3 steps apart','? times']),check:C('solution A has a pH of 4 and solution B has a pH of 7. How many times more acidic is A than B?',1000,[3,30,1000],'Three tenfold steps: 10 × 10 × 10 = 1,000.')}]},

/* English 9, Reading Literature. Claims, evidence and inference as in the Common Core State Standards, RL.9-10.1 ("Cite strong and thorough
   textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text"; corestandards.org). The
   passage is fictional and written for this Quick start. Limits: "strongest evidence" in the second Try-it is a reading judgement; the other
   choices are weaker, not wrong facts. */
'language-h-english-9-reading-literature':{review:'Facts reviewed 3 Nov 2026: stated versus inferred meaning and textual evidence follow Common Core RL.9-10.1 (corestandards.org). The passage is fictional. Limits: the second Try-it asks for the strongest evidence, a reading judgement.',steps:[
 {say:'Reading literature closely means making claims about a text and backing them with evidence. A claim is a statement about the text. Evidence is the exact words that support it.',pic:B('Close reading',['claim','evidence'],['a statement about the text','the exact words'])},
 {say:'Some things a text states outright. Others a reader infers: a conclusion drawn from clues in the text plus what the reader already knows.',pic:B('Stated or inferred?',['stated: the words say it','inferred: clues + what you know'])},
 {say:'Read this fictional passage. The text states that Mara checked the clock, tapped her pen and read one line three times. It never says how she feels.',pic:PS('Fictional passage',['Mara checked the clock again, tapped her pen, and read the same line for the third time.'])},
 {say:'Your turn. Find the one the passage never says in words.',pic:PS('Fictional passage',['Mara checked the clock again, tapped her pen, and read the same line for the third time.']),check:C(ABC('in the passage, which of these is an inference, not something the text states?','Mara checked the clock','Mara is distracted','Mara read a line three times'),'B',['A','B','C'],'The text never says she is distracted; you work that out from the clues.')},
 {say:'A good inference points to its clues. “Mara is distracted” rests on two: she keeps checking the clock, and she reads the same line again and again.',pic:B('An inference and its clues',['Mara is distracted','checks the clock','rereads one line'])},
 {say:'Match the claim to the words that support it best.',pic:PS('Fictional passage',['Mara checked the clock again, tapped her pen, and read the same line for the third time.']),check:C(ABC('a student claims Mara is waiting for something. Which words are the strongest evidence?','“tapped her pen”','“checked the clock again”','“the same line”'),'B',['A','B','C'],'Checking the clock again and again is what someone waiting does.')},
 {say:'Claim, evidence and inference are the core of close reading. The full lesson goes on to theme, character and an author\'s choices.',pic:B('Close reading',['claim','evidence','inference'])}]},

/* English 10, Literary Analysis: claim, evidence and commentary (the paragraph moves the full lesson teaches, written to Common Core RL.9-10.1;
   corestandards.org). The passage is fictional. Limits: none beyond the reading judgements the Try-its ask for. */
'language-h-english-10-literary-analysis':{review:'Facts reviewed 3 Nov 2026: claim, evidence and commentary follow Common Core RL.9-10.1 (corestandards.org) and the full lesson\'s terms. The passage is fictional. Limits: the Try-its are reading judgements with one clear best answer.',steps:[
 {say:'Literary analysis is an argument about a text. It is built from three moves: a claim, evidence and commentary.',pic:B('Three moves',['Claim','Evidence','Commentary'],['your arguable point','the exact words','your explanation'])},
 {say:'The claim is your arguable point about the text, something a reader could disagree with. “The story has a dog in it” is a plain fact, not a claim.',pic:B('Claim or fact?',['the story has a dog: a fact','the dog stands for loyalty: a claim'])},
 {say:'The evidence is the exact words from the text that support your claim, quoted carefully.',pic:B('Evidence',['the exact words','in quotation marks'])},
 {say:'The commentary explains how those words support the claim. Without it, the reader has to guess the link.',pic:B('Commentary',['explains the link','between words and claim'])},
 {say:'Read this fictional passage and three sentences a student wrote about it, then find the commentary.',pic:PS('Fictional passage',['Every night Jun left the porch light on, though his brother had not come home in a year.','1. Jun misses his brother.','2. “Every night Jun left the porch light on.”','3. Leaving the light on every night shows that Jun still expects his brother back.']),check:C(ABC('which sentence is the commentary?','Sentence 1','Sentence 2','Sentence 3'),'C',['A','B','C'],'Commentary explains how the quoted words support the claim: sentence 3.')},
 {say:'Now tell an arguable point from a plain fact.',pic:PS('Three statements',['1. Jun leaves a light on.','2. Jun has not given up hope.','3. The passage is one sentence long.']),check:C(ABC('which statement is a claim, not a plain fact?','Statement 1','Statement 2','Statement 3'),'B',['A','B','C'],'A claim is a point a reader could argue with: statement 2.')},
 {say:'Claim, evidence and commentary, in that order, make one paragraph of analysis. The full lesson builds whole essays from these paragraphs.',pic:B('One paragraph',['claim','evidence','commentary'])}]},

/* AP English Language and Composition, the rhetorical situation. Purpose and intended audience as course skills (College Board AP Students
   course page, Unit 1: "Identifying the purpose and intended audience of a text"); the rhetorical situation, its author, audience,
   purposes (rarely only one) and setting (time, place and environment) (Purdue OWL, "Rhetorical Situations" and "Elements of Rhetorical
   Situations"). The note is fictional. Limits: "exigence" is left to the full lesson (no primary definition was read this pass). */
'language-h-ap-lang-rhetorical-situation':{review:'Facts reviewed 3 Nov 2026: purpose and intended audience from the College Board AP English Language course page (Unit 1); writer, audience, purposes and setting from Purdue OWL, "Rhetorical Situations" and "Elements of Rhetorical Situations". The note is fictional. Limits: "exigence" is left to the full lesson.',steps:[
 {say:'Every text is written by someone, for someone, for a reason. AP English Language calls this the rhetorical situation.',pic:B('The rhetorical situation',['by someone','for someone','for a reason'])},
 {say:'The writer is the person who creates the text. The audience is the people it is meant to reach.',pic:B('Who?',['writer','audience'],['who creates it','who it is for'])},
 {say:'The purpose is what the writer wants the text to do: to persuade, to inform, to warn or to ask for something. A text can have more than one purpose.',pic:B('Why?',['persuade','inform','warn or ask'])},
 {say:'The context is the time, place and circumstances around the text. The same words can work differently in a different setting.',pic:B('Context',['time','place','circumstances'])},
 {say:'Read this fictional note, then name its audience.',pic:PS('Fictional note on a vending machine',['Students: this machine eats coins. Until it is fixed on Friday, please use the one in the gym.']),check:C(ABC('who is the audience of the note?','the repair company','students','the gym teacher'),'B',['A','B','C'],'The note speaks to “Students” directly.')},
 {say:'Now name what the note is trying to do.',pic:PS('Fictional note on a vending machine',['Students: this machine eats coins. Until it is fixed on Friday, please use the one in the gym.']),check:C(ABC('what is the note\'s main purpose?','to send students to another machine','to sell snacks','to praise the gym'),'A',['A','B','C'],'It asks students to use the machine in the gym until Friday.')},
 {say:'Writer, audience, purpose and context: name them, and you can explain a writer\'s choices. The full lesson adds what prompts a text and how arguments reach their audience.',pic:B('Name the situation',['writer','audience','purpose','context'])}]},

/* AP English Literature and Composition, Short Fiction I: setting (time, place and social world) and what it does. The passage is fictional.
   Limits: no facts about published works are stated; setting is defined as the full lesson defines it. */
'language-h-ap-lit-short-fiction':{review:'Facts reviewed 3 Nov 2026: no facts about published works are stated; the setting terms follow the full lesson and the AP Literature Big Idea Setting (SET). The passage is fictional. Limits: the Try-its are reading judgements with one clear best answer.',steps:[
 {say:'Setting is where and when a story happens, and also the social world its characters live in.',pic:B('Setting',['where','when','the social world'])},
 {say:'In AP Literature you ask what a setting does, not only where it is. Details of place can show what a community values and what a character is up against.',pic:B('What a setting does',['shows what people value','shows what they are up against'])},
 {say:'Read this fictional passage. Notice the details: a closed mill, the same four men, and silence.',pic:PS('Fictional passage',['The mill had closed in spring. By August the town’s one diner served coffee to the same four men, who sat apart and did not talk.'])},
 {say:'Your turn. What do the details add up to?',pic:PS('Fictional passage',['The mill had closed in spring. By August the town’s one diner served coffee to the same four men, who sat apart and did not talk.']),check:C(ABC('what does the setting suggest about the town?','It is busy and growing','It has lost work, and its people have drifted apart','It is a holiday resort'),'B',['A','B','C'],'A closed mill and four silent men point to lost work and distance.')},
 {say:'A strong reading follows a chain: notice a detail, say what it shows, then ask how it bears on the story’s conflict or theme.',pic:B('A reading chain',['notice a detail','say what it shows','link it to the theme'])},
 {say:'Find the comment that says what a detail means.',pic:PS('Fictional passage',['The mill had closed in spring. By August the town’s one diner served coffee to the same four men, who sat apart and did not talk.']),check:C(ABC('which comment goes beyond naming the place?','The story is set in a diner','The silence suggests the closing has cut people off from each other','There are four men'),'B',['A','B','C'],'A strong reading says what the detail shows, not only what it is.')},
 {say:'A weak reading names the place; a strong one says what the place means. The full lesson goes on to character, structure and narration in short fiction.',pic:B('Setting',['name it','then say what it means'])}]},

/* Personal Finance, Budgeting a paycheck. Gross pay is pay before deductions, net pay is gross minus all deductions, the take-home pay
   (CFPB, "Understanding your pay stub"; IRS Understanding Taxes, payroll taxes); typical deductions include Social Security and Medicare taxes,
   income tax withheld and health insurance premiums (IRS Understanding Taxes; FDIC Money Smart, grades 9-12). All dollar amounts fictional;
   800 - 120 = 680, 680 - (300 + 150 + 100) = 130 by derivation. Limits: fixed and variable expenses are described in general terms. */
'finance-h-budget':{review:'Facts reviewed 3 Nov 2026: gross pay, net pay and typical deductions from the CFPB, "Understanding your pay stub", IRS Understanding Taxes (payroll taxes and withholding) and FDIC Money Smart (grades 9-12); arithmetic by derivation. Limits: every amount is fictional; expenses are described in general terms.',steps:[
 {say:'A budget is a plan for your money: what comes in, and where it goes. It starts with knowing how much you actually take home.',pic:B('A budget',['money in','money out','what is left'])},
 {say:'Gross pay is what you earn before deductions. Deductions, such as income tax, Social Security and Medicare taxes, and health insurance, come out of it.',pic:B('Gross pay',['earned before deductions'])},
 {say:'Net pay is gross pay minus all the deductions: the take-home pay that actually reaches you. Budget from net pay, not gross pay.',pic:B('Net pay',['gross pay - deductions','= take-home pay'])},
 {say:'Your turn. Take the deductions away from the gross pay.',pic:B('A fictional paycheck',['gross pay: $800','deductions: $120 in all','net pay: ?']),check:C('a fictional paycheck shows gross pay of $800 and deductions of $120 in all. What is the net pay, in dollars?',680,[680,800,920],'Net pay = gross pay - deductions: 800 - 120.')},
 {say:'Next, list your expenses. Some, like a phone plan, stay about the same each month. Others, like food or fun, change from month to month.',pic:B('Expenses',['about the same each month','change month to month'],['a phone plan','food, fun'])},
 {say:'Add the planned expenses, then take them away from the net pay.',pic:B('Fictional Ana\'s month',['take-home: $680','rent $300, food $150, transport $100','left: ?']),check:C('fictional Ana takes home $680 and plans $300 for rent, $150 for food and $100 for transport. How many dollars are left to save or spend?',130,[130,230,550],'300 + 150 + 100 = 550, and 680 - 550 = 130.')},
 {say:'Money in, expenses out, and what is left is yours to save or plan. The full lesson goes on to reading a whole pay stub and building a monthly budget.',pic:B('The budget loop',['take-home pay','minus expenses','= what is left'])}]},

/* AP Macroeconomics, Unit 1, Basic Economic Concepts ("Scarcity"; "Opportunity cost and the Production Possibilities Curve", College Board AP
   Students course page). Scarcity as not enough resources to produce everyone's wants; opportunity cost as the value of the next-best
   alternative given up; any choice has one even at a zero price (Federal Reserve Bank of St. Louis, Economic Lowdown glossary and "There Is No
   Such Thing as a Free Lunch"). People and amounts fictional. Limits: Lee's choice values only the money from each job. */
'finance-h-ap-macro-basic-economic-concepts':{review:'Facts reviewed 3 Nov 2026: Unit 1 topics from the College Board AP Macroeconomics course page; scarcity, opportunity cost as the next-best alternative, and choices with no price from the Federal Reserve Bank of St. Louis (Economic Lowdown glossary; "There Is No Such Thing as a Free Lunch"). Limits: the people and amounts are fictional; Lee\'s example counts only money.',steps:[
 {say:'Economics starts with scarcity: there are not enough resources to produce everything people want.',pic:B('Scarcity',['wants: unlimited','resources: limited'])},
 {say:'Because of scarcity, people, businesses and governments must choose, and every choice gives something up.',pic:B('Choosing',['one option chosen','others given up'])},
 {say:'Opportunity cost is the value of the next-best alternative you give up when you choose. It is not every option you skipped, only the best one.',pic:B('Opportunity cost',['the next-best alternative','that you give up'])},
 {say:'Your turn. Find the best option Lee did not take, counting only money.',pic:B('Fictional Lee\'s evening',['work a shift: $40','babysit: $30','go to a concert (chosen)']),check:C(ABC('fictional Lee has one free evening. He could work a shift for $40, babysit for $30, or go to a concert. He picks the concert. Counting only money, what is his opportunity cost?','the $40 shift','$70, both jobs','the $30 babysitting'),'A',['A','B','C'],'Only the next-best alternative counts: the $40 shift.')},
 {say:'Opportunity cost applies to things with no price, too: an hour spent on a game is an hour not spent on anything else.',pic:B('No price, still a cost',['an hour on a game','is an hour not spent elsewhere'])},
 {say:'One more, with no money at all.',pic:B('A fictional field',['a park (chosen)','a parking lot']),check:C(ABC('a fictional town can use one field for a park or for a parking lot, and it chooses the park. What is the opportunity cost?','the parking lot it gave up','the park','nothing, because the field was free'),'A',['A','B','C'],'The opportunity cost is the next-best use given up: the parking lot.')},
 {say:'Scarcity forces choices, and every choice has an opportunity cost. The full lesson goes on to the factors of production and the production possibilities curve.',pic:B('The basic idea',['scarcity','choice','opportunity cost'])}]}
};
